(function(){
const {R,pick,shuffle,sample,range,plural}=H;
const N=x=>H.num(x);
const fr=(a,b)=>H.frac(a,b);
const M=s=>`<span class="m">${s}</span>`;
/* многочлен: [[коэф,'x²'],[коэф,'x'],[коэф,'']] → «x² − 6x + 9» */
function P(terms){let s='';terms.forEach(([c,v])=>{if(c===0)return;const a=Math.abs(c);const t=(a===1&&v)?v:(N(a)+v);
  if(!s)s=(c<0?'−':'')+t;else s+=(c<0?' − ':' + ')+t;});return s||'0';}
const B=(m,v,n)=>P([[m,v],[n,'']]);         // двучлен m·v + n
const sgn=(n)=>n<0?'−':'+';
function mk(correct,traps){const o=[correct];traps.forEach(t=>{if(!o.includes(t))o.push(t);});const s=shuffle(o);return {opts:s,ans:s.indexOf(correct)};}
const VARS=['x','a','y','m','b'];
const sup=n=>`<sup>${n}</sup>`;

/* ---------- рисунки ---------- */
const T=(x,y,t,o)=>`<text x="${x}" y="${y}" text-anchor="${(o&&o.a)||'middle'}" font-size="${(o&&o.s)||16}" font-weight="${(o&&o.w)||700}" fill="${(o&&o.c)||'var(--ink)'}">${t}</text>`;
function figSum(){
  const x0=60,y0=34,a=130,b=70;
  let s=`<svg viewBox="0 0 320 300" width="320" role="img" aria-label="Квадрат со стороной a + b" style="font-family:system-ui,sans-serif">`;
  s+=`<rect x="${x0}" y="${y0}" width="${a}" height="${a}" fill="var(--hl)" fill-opacity=".55"/>`;
  s+=`<rect x="${x0+a}" y="${y0}" width="${b}" height="${a}" fill="var(--accent)" fill-opacity=".22"/>`;
  s+=`<rect x="${x0}" y="${y0+a}" width="${a}" height="${b}" fill="var(--accent)" fill-opacity=".22"/>`;
  s+=`<rect x="${x0+a}" y="${y0+a}" width="${b}" height="${b}" fill="var(--hl)" fill-opacity=".25"/>`;
  s+=`<rect x="${x0}" y="${y0}" width="${a+b}" height="${a+b}" fill="none" stroke="var(--fig)" stroke-width="1.8"/>`;
  s+=`<line x1="${x0+a}" y1="${y0}" x2="${x0+a}" y2="${y0+a+b}" stroke="var(--fig)" stroke-width="1.4"/><line x1="${x0}" y1="${y0+a}" x2="${x0+a+b}" y2="${y0+a}" stroke="var(--fig)" stroke-width="1.4"/>`;
  s+=T(x0+a/2,y0-10,'a',{c:'var(--accent-ink)'})+T(x0+a+b/2,y0-10,'b',{c:'var(--accent-ink)'});
  s+=T(x0-14,y0+a/2+5,'a',{c:'var(--accent-ink)'})+T(x0-14,y0+a+b/2+5,'b',{c:'var(--accent-ink)'});
  s+=T(x0+a/2,y0+a/2+7,'a²',{s:22})+T(x0+a+b/2,y0+a/2+6,'ab',{s:18})+T(x0+a/2,y0+a+b/2+6,'ab',{s:18})+T(x0+a+b/2,y0+a+b/2+6,'b²',{s:18});
  s+=T(160,y0+a+b+34,'(a + b)² = a² + ab + ab + b²',{s:15,w:600});
  return s+'</svg>';
}
function figDiff(){
  const x0=60,y0=34,c=130,b=70;   // c = a − b
  let s=`<svg viewBox="0 0 320 300" width="320" role="img" aria-label="Квадрат разности" style="font-family:system-ui,sans-serif">`;
  s+=`<rect x="${x0}" y="${y0}" width="${c}" height="${c}" fill="var(--hl)" fill-opacity=".55"/>`;
  s+=`<rect x="${x0+c}" y="${y0}" width="${b}" height="${c}" fill="var(--accent)" fill-opacity=".14"/>`;
  s+=`<rect x="${x0}" y="${y0+c}" width="${c}" height="${b}" fill="var(--accent)" fill-opacity=".14"/>`;
  s+=`<rect x="${x0+c}" y="${y0+c}" width="${b}" height="${b}" fill="var(--accent)" fill-opacity=".32"/>`;
  s+=`<rect x="${x0}" y="${y0}" width="${c+b}" height="${c+b}" fill="none" stroke="var(--fig)" stroke-width="1.8"/>`;
  s+=`<line x1="${x0+c}" y1="${y0}" x2="${x0+c}" y2="${y0+c+b}" stroke="var(--fig)" stroke-width="1.4" stroke-dasharray="5 4"/><line x1="${x0}" y1="${y0+c}" x2="${x0+c+b}" y2="${y0+c}" stroke="var(--fig)" stroke-width="1.4" stroke-dasharray="5 4"/>`;
  s+=T(x0+c/2,y0-10,'a − b',{c:'var(--accent-ink)',s:15})+T(x0+c+b/2,y0-10,'b',{c:'var(--accent-ink)'});
  s+=T(x0-10,y0+c/2+5,'a − b',{c:'var(--accent-ink)',s:15,a:'end'})+T(x0-14,y0+c+b/2+5,'b',{c:'var(--accent-ink)'});
  s+=T(x0+c/2,y0+c/2+7,'(a − b)²',{s:19})+T(x0+c+b/2,y0+c/2+5,'ab − b²',{s:13,w:600})+T(x0+c/2,y0+c+b/2+5,'ab − b²',{s:13,w:600})+T(x0+c+b/2,y0+c+b/2+6,'b²',{s:17});
  s+=T(160,y0+c+b+34,'весь квадрат: a × a = a²',{s:15,w:600});
  return s+'</svg>';
}
function figDsq(){
  // слева квадрат a без уголка b, справа — тот же кусок, переложенный в прямоугольник (a+b)×(a−b)
  const a=100,b=40,c=a-b,x0=16,y0=44,rx=180,ry=74;
  let s=`<svg viewBox="0 0 330 190" width="330" role="img" aria-label="Разность квадратов" style="font-family:system-ui,sans-serif">`;
  s+=`<rect x="${x0}" y="${y0}" width="${a}" height="${c}" fill="var(--hl)" fill-opacity=".55" stroke="var(--fig)" stroke-width="1.4"/>`;
  s+=`<rect x="${x0}" y="${y0+c}" width="${c}" height="${b}" fill="var(--accent)" fill-opacity=".28" stroke="var(--fig)" stroke-width="1.4"/>`;
  s+=`<rect x="${x0+c}" y="${y0+c}" width="${b}" height="${b}" fill="none" stroke="var(--fig)" stroke-width="1.2" stroke-dasharray="4 4"/>`;
  s+=T(x0+c+b/2,y0+c+b/2+5,'b²',{s:14,c:'var(--muted)',w:600});
  s+=T(x0+a/2,y0-10,'a',{c:'var(--accent-ink)'})+T(x0+a+10,y0+c+b/2+5,'b',{c:'var(--accent-ink)',a:'start'});
  s+=T(x0+a/2,y0+c/2+6,'1',{s:18})+T(x0+c/2,y0+c+b/2+6,'2',{s:18});
  s+=T(x0+a/2,y0+a+28,'a² − b²',{s:15,w:600});
  s+=`<path d="M${x0+a+30},104 L${rx-14},104" stroke="var(--fig)" stroke-width="1.6"/><path d="M${rx-16},99 L${rx-6},104 L${rx-16},109 Z" fill="var(--fig)"/>`;
  s+=`<rect x="${rx}" y="${ry}" width="${a}" height="${c}" fill="var(--hl)" fill-opacity=".55" stroke="var(--fig)" stroke-width="1.4"/>`;
  s+=`<rect x="${rx+a}" y="${ry}" width="${b}" height="${c}" fill="var(--accent)" fill-opacity=".28" stroke="var(--fig)" stroke-width="1.4"/>`;
  s+=T(rx+a/2,ry+c/2+6,'1',{s:18})+T(rx+a+b/2,ry+c/2+6,'2',{s:18});
  s+=T(rx+a/2,ry-10,'a',{c:'var(--accent-ink)'})+T(rx+a+b/2,ry-10,'b',{c:'var(--accent-ink)'});
  s+=T(rx+(a+b)/2,ry+c+26,'(a + b)(a − b)',{s:15,w:600});
  return s+'</svg>';
}

/* ---------- теория ---------- */
const theory=[
{title:'Зачем нужны формулы сокращённого умножения',lvl:0,html:`
<p>Иногда приходится много раз умножать одни и те же «скобки», например (x + 3)(x + 3). Математики заметили закономерности и записали их в виде готовых формул — как таблицу умножения, только для скобок. Это экономит время и помогает считать в уме.</p>
<div class="box rule"><b>Слова, которые встретятся</b>
<b>Квадрат</b> числа — число, умноженное само на себя: a² = a · a.<br>
<b>Произведение</b> — результат умножения: ab = a · b.<br>
<b>Удвоенное произведение</b> — произведение, умноженное на 2: 2ab.<br>
<b>Куб</b> — число, умноженное само на себя три раза: a³ = a · a · a.</div>
<p>Формул семь. Все они проверяются простым раскрытием скобок — поэтому если забыл формулу, её всегда можно вывести заново.</p>`},
{title:'Квадрат суммы: (a + b)² = a² + 2ab + b²',lvl:0,html:`
<p>Раскроем скобки: (a + b)² = (a + b)(a + b) = a² + ab + ba + b² = <b>a² + 2ab + b²</b>.</p>
<div class="box rule"><b>Формула и как её читать</b><span class="m">(a + b)² = a² + 2ab + b²</span><br>«Квадрат суммы двух чисел равен квадрату первого, плюс удвоенное произведение первого на второе, плюс квадрат второго».</div>
<p>Картинка: большой квадрат со стороной a + b разрезан на 4 части — квадрат a², квадрат b² и <b>два</b> одинаковых прямоугольника ab. Отсюда и «2ab».</p>
<div class="fig">${figSum()}</div>
<div class="box ex"><b>Пример</b>(x + 3)² = x² + 2 · x · 3 + 3² = x² + 6x + 9.<br>(2a + 5)² = (2a)² + 2 · 2a · 5 + 5² = 4a² + 20a + 25.</div>
<div class="box err"><b>Самая частая ошибка</b><span class="m">(a + b)² ≠ a² + b²</span>! На картинке это значит «забыли два прямоугольника».<br>Проверка числами: (2 + 3)² = 5² = 25, а 2² + 3² = 4 + 9 = 13. Не равно! Разница 12 = 2 · 2 · 3 — это и есть 2ab.</div>
<div class="box err"><b>Вторая ошибка</b>Забыть возвести в квадрат коэффициент: (2a)² = 4a², а не 2a².</div>`},
{title:'Квадрат разности: (a − b)² = a² − 2ab + b²',lvl:1,html:`
<p>Всё так же, только удвоенное произведение идёт со знаком <b>минус</b>. Последнее слагаемое b² — всегда с <b>плюсом</b> (минус на минус).</p>
<div class="box rule"><b>Формула</b><span class="m">(a − b)² = a² − 2ab + b²</span><br>«Квадрат разности равен квадрату первого, минус удвоенное произведение, плюс квадрат второго».</div>
<div class="fig">${figDiff()}</div>
<p class="small" style="text-align:center">Из квадрата a² вырезаем две полосы. Каждая полоса вместе с уголком — это ab, поэтому ab − b² без уголка. Получаем (a − b)² = a² − 2(ab − b²) − b² = a² − 2ab + b².</p>
<div class="box ex"><b>Пример</b>(x − 4)² = x² − 2 · x · 4 + 4² = x² − 8x + 16.<br>(3a − 2b)² = 9a² − 12ab + 4b².</div>
<div class="box err"><b>Ловушки</b>(x − 4)² ≠ x² − 16 (это другая формула).<br>(x − 4)² ≠ x² − 8x − 16: в конце всегда <b>+</b>, ведь (−4)² = 16.</div>
<div class="box tip"><b>Как запомнить знаки</b>В квадрате суммы все знаки «+». В квадрате разности знаки идут «+ − +» — минус только посередине.</div>`},
{title:'Разность квадратов: a² − b² = (a − b)(a + b)',lvl:2,html:`
<p>Перемножим (a − b)(a + b) = a² + ab − ab − b² = <b>a² − b²</b>. Средние слагаемые уничтожили друг друга!</p>
<div class="box rule"><b>Формула</b><span class="m">(a − b)(a + b) = a² − b²</span><br>«Произведение разности двух чисел на их сумму равно разности их квадратов».<br>Справа налево: «разность квадратов раскладывается на множители — разность и сумму».</div>
<div class="fig">${figDsq()}</div>
<p class="small" style="text-align:center">Из квадрата a² вырезали уголок b². Оставшиеся куски 1 и 2 переложили — получился прямоугольник со сторонами a + b и a − b.</p>
<div class="box ex"><b>Пример в обе стороны</b>Раскрыть: (x − 5)(x + 5) = x² − 25.<br>Разложить: 9y² − 49 = (3y)² − 7² = (3y − 7)(3y + 7).</div>
<div class="box err"><b>Ловушка</b>Сумма квадратов <b>a² + b²</b> так не раскладывается! x² + 25 ≠ (x + 5)(x − 5).</div>`},
{title:'Считаем в уме с помощью формул',lvl:3,html:`
<p>Формулы — отличный способ считать большие числа без калькулятора. Секрет: представь число как «круглое ± немного».</p>
<div class="box ex"><b>Квадрат числа около круглого</b>99² = (100 − 1)² = 10000 − 200 + 1 = <b>9801</b>.<br>51² = (50 + 1)² = 2500 + 100 + 1 = <b>2601</b>.</div>
<div class="box ex"><b>Произведение «симметричных» чисел</b>51 · 49 = (50 + 1)(50 − 1) = 2500 − 1 = <b>2499</b>.<br>102 · 98 = 100² − 2² = 10000 − 4 = <b>9996</b>.</div>
<div class="box ex"><b>Разность квадратов больших чисел</b>101² − 99² = (101 − 99)(101 + 99) = 2 · 200 = <b>400</b>. Не нужно возводить в квадрат!</div>
<div class="box tip"><b>Как заметить</b>Если два множителя одинаково отстоят от круглого числа (51 и 49 — оба на 1 от 50), — это разность квадратов.</div>`},
{title:'Разложение на множители. Полный квадрат',lvl:4,html:`
<p>Формулы работают и <b>справа налево</b>: длинное выражение «сворачиваем» в скобку. Это называется <b>разложить на множители</b>.</p>
<div class="box rule"><b>Как узнать полный квадрат</b>Трёхчлен — полный квадрат, если:<br>1) два слагаемых — квадраты (x² и 25 = 5²);<br>2) третье слагаемое — <b>удвоенное произведение</b> их «оснований» (2 · x · 5 = 10x).<br>Тогда x² − 10x + 25 = (x − 5)². Знак в скобке — как знак у удвоенного произведения.</div>
<ol class="steps"><li>Нашёл квадраты: 4a² = (2a)², 9 = 3².</li><li>Проверил середину: 2 · 2a · 3 = 12a. В выражении 4a² + 12a + 9 стоит именно 12a ✅.</li><li>Ответ: (2a + 3)².</li></ol>
<div class="box err"><b>Не полный квадрат</b>x² + 5x + 25: квадраты есть (x² и 5²), но удвоенное произведение должно быть 10x, а не 5x. Значит, это <b>не</b> полный квадрат.</div>`},
{title:'Куб суммы и куб разности',lvl:5,html:`
<div class="box rule"><b>Формулы</b><span class="m">(a + b)³ = a³ + 3a²b + 3ab² + b³</span><br><span class="m">(a − b)³ = a³ − 3a²b + 3ab² − b³</span><br>«Куб суммы равен кубу первого, плюс утроенное произведение квадрата первого на второе, плюс утроенное произведение первого на квадрат второго, плюс куб второго».</div>
<div class="box tip"><b>Как запомнить</b>Коэффициенты <b>1, 3, 3, 1</b>. Степень a идёт вниз: 3, 2, 1, 0. Степень b — вверх: 0, 1, 2, 3.<br>В кубе разности знаки <b>чередуются</b>: + − + −.</div>
<div class="box ex"><b>Пример</b>(x + 2)³ = x³ + 3 · x² · 2 + 3 · x · 4 + 8 = x³ + 6x² + 12x + 8.<br>(x − 1)³ = x³ − 3x² + 3x − 1.</div>
<div class="box err"><b>Ловушка</b>(a + b)³ ≠ a³ + b³. Проверка: (1 + 1)³ = 8, а 1³ + 1³ = 2.</div>`},
{title:'Сумма и разность кубов',lvl:6,html:`
<div class="box rule"><b>Формулы</b><span class="m">a³ − b³ = (a − b)(a² + ab + b²)</span><br><span class="m">a³ + b³ = (a + b)(a² − ab + b²)</span></div>
<p>Вторую скобку называют <b>неполным квадратом</b>: она похожа на квадрат суммы или разности, но посередине просто ab, а не 2ab.</p>
<div class="box tip"><b>Как запомнить знаки</b>Первая скобка — <b>тот же</b> знак, что между кубами. Посередине второй скобки — <b>противоположный</b>. В конце — <b>всегда плюс</b>.</div>
<div class="box ex"><b>Пример</b>x³ − 8 = x³ − 2³ = (x − 2)(x² + 2x + 4).<br>27a³ + 1 = (3a)³ + 1³ = (3a + 1)(9a² − 3a + 1).</div>
<div class="box err"><b>Ловушка</b>x³ − 8 ≠ (x − 2)³ и ≠ (x − 2)(x² + 4x + 4). Во второй скобке посередине 2x, а не 4x.</div>
<p>Проверить можно раскрытием скобок: (x − 2)(x² + 2x + 4) = x³ + 2x² + 4x − 2x² − 4x − 8 = x³ − 8 ✅.</p>`},
{title:'Выделение полного квадрата. Наименьшее значение',lvl:7,html:`
<p>Как найти наименьшее значение выражения x² − 6x + 11? Превратим его в «квадрат + число».</p>
<ol class="steps"><li>Смотрим на x² − 6x. Это начало квадрата разности: (x − 3)² = x² − 6x + 9. (Число в скобке — половина от 6.)</li>
<li>Значит, x² − 6x + 11 = (x² − 6x + 9) + 2 = <b>(x − 3)² + 2</b>.</li>
<li>Квадрат всегда ≥ 0, а = 0 он только при x = 3. Поэтому наименьшее значение равно <b>2</b> (при x = 3).</li></ol>
<div class="box tip"><b>Аналогия</b>(x − 3)² — это «плата», которая никогда не бывает отрицательной. Минимум — когда платить ничего не надо (x = 3). Тогда остаётся только «+2».</div>
<div class="box err"><b>Ловушка</b>Добавил 9 — не забудь вычесть 9: x² − 6x + 11 = (x − 3)² − 9 + 11. Ответ «11» неверен.</div>`},
{title:'Комбинированные задачи и уравнения',lvl:8,html:`
<p>Если в уравнении есть квадраты скобок, раскрой их по формулам — часто x² сокращается и уравнение становится простым.</p>
<div class="box ex"><b>Пример</b>(x + 3)² − (x − 3)² = 24.<br>(x² + 6x + 9) − (x² − 6x + 9) = 24<br>x² + 6x + 9 − x² + 6x − 9 = 24 (минус перед скобкой меняет все знаки!)<br>12x = 24 → x = 2.</div>
<div class="box err"><b>Самая коварная ошибка</b>Минус перед скобкой: −(x − 3)² = −(x² − 6x + 9) = −x² + 6x − 9. Меняются <b>все три</b> знака.</div>
<div class="box tip"><b>Сворачивание</b>37² + 2 · 37 · 13 + 13² = (37 + 13)² = 50² = 2500 — формула «наоборот».</div>`},
{title:'★ Олимпиадные приёмы',lvl:9,html:`
<h3>1) Цепочка разностей квадратов</h3>
<p>(2 + 1)(2² + 1)(2⁴ + 1)(2⁸ + 1). Умножим на (2 − 1) = 1 — значение не изменится:<br>(2 − 1)(2 + 1) = 2² − 1, потом (2² − 1)(2² + 1) = 2⁴ − 1, потом 2⁸ − 1, потом 2${sup(16)} − 1. Ответ: 2${sup(16)} − 1 = 65535.</p>
<p>Отсюда же видно: 2${sup(16)} − 1 = (2⁸ − 1)(2⁸ + 1) = 3 · 5 · 17 · 257 — делится на 3, 5, 17 и 257.</p>
<h3>2) Сумма квадратов ≥ 0</h3>
<p>x² + y² − 4x + 6y + 20 = (x − 2)² + (y + 3)² + 7. Оба квадрата ≥ 0, значит, наименьшее значение — 7 (при x = 2, y = −3).</p>
<h3>3) Знаем a + b и ab — находим всё остальное</h3>
<p>a² + b² = (a + b)² − 2ab, &nbsp; a³ + b³ = (a + b)³ − 3ab(a + b).<br>Если a + b = 5, ab = 3: a² + b² = 25 − 6 = 19; a³ + b³ = 125 − 45 = 80.</p>
<p>Похожий приём: если x + ${fr(1,'x')} = 3, то x² + ${fr(1,'x²')} = 3² − 2 = 7 (удвоенное произведение x · ${fr(1,'x')} = 1).</p>
<h3>4) Произведение четырёх подряд идущих чисел + 1</h3>
<p>n(n + 1)(n + 2)(n + 3) + 1 = (n² + 3n + 1)² — всегда полный квадрат. Например, 1 · 2 · 3 · 4 + 1 = 25 = 5².</p>`},
{title:'Шпаргалка',html:`
<ul class="steps">
<li>(a + b)² = a² + 2ab + b²; (a − b)² = a² − 2ab + b². Не забывай 2ab!</li>
<li>a² − b² = (a − b)(a + b). Сумма квадратов не раскладывается.</li>
<li>(a ± b)³ = a³ ± 3a²b + 3ab² ± b³ (коэффициенты 1, 3, 3, 1).</li>
<li>a³ ± b³ = (a ± b)(a² ∓ ab + b²): тот же знак, противоположный, всегда плюс.</li>
<li>Наименьшее значение — выдели полный квадрат: x² − 6x + 11 = (x − 3)² + 2.</li>
<li>Минус перед скобкой меняет все знаки внутри.</li></ul>`}
];

/* ---------- формулы ---------- */
const F=s=>`<span style="font-size:17px;white-space:nowrap">${s}</span>`;
const symbols={tab:'Формулы',title:'Все формулы: как читать и пример',rows:[
[F('(a + b)² =<br>a² + 2ab + b²'),'Квадрат суммы','«Квадрат первого, плюс удвоенное произведение первого на второе, плюс квадрат второго».',M('(x + 3)² = x² + 6x + 9')],
[F('(a − b)² =<br>a² − 2ab + b²'),'Квадрат разности','«Квадрат первого, минус удвоенное произведение, плюс квадрат второго». Последний знак — всегда плюс.',M('(x − 4)² = x² − 8x + 16')],
[F('a² − b² =<br>(a − b)(a + b)'),'Разность квадратов','«Разность квадратов равна произведению разности на сумму». Работает в обе стороны.',M('x² − 25 = (x − 5)(x + 5)')],
[F('(a + b)³ =<br>a³ + 3a²b + 3ab² + b³'),'Куб суммы','«Куб первого, плюс утроенный квадрат первого на второе, плюс утроенное первое на квадрат второго, плюс куб второго». Коэффициенты 1, 3, 3, 1.',M('(x + 1)³ = x³ + 3x² + 3x + 1')],
[F('(a − b)³ =<br>a³ − 3a²b + 3ab² − b³'),'Куб разности','То же, но знаки чередуются: + − + −.',M('(x − 2)³ = x³ − 6x² + 12x − 8')],
[F('a³ + b³ =<br>(a + b)(a² − ab + b²)'),'Сумма кубов','«Сумма кубов равна произведению суммы на неполный квадрат разности».',M('x³ + 27 = (x + 3)(x² − 3x + 9)')],
[F('a³ − b³ =<br>(a − b)(a² + ab + b²)'),'Разность кубов','«Разность кубов равна произведению разности на неполный квадрат суммы».',M('x³ − 8 = (x − 2)(x² + 2x + 4)')],
[F('2ab'),'Удвоенное произведение','Произведение двух чисел, умноженное на 2. Средний член квадрата суммы или разности.',M('a = x, b = 5: 2ab = 10x')],
[F('a² ± ab + b²'),'Неполный квадрат','Похож на квадрат суммы/разности, но посередине ab, а не 2ab. Встречается в формулах кубов.',M('x² + 2x + 4')],
[F('(x − p)² + q'),'Выделение полного квадрата','Наименьшее значение равно q (при x = p), потому что квадрат ≥ 0.',M('x² − 6x + 11 = (x − 3)² + 2')]
],after:`<div class="box err" style="margin-top:14px"><b>Главная ошибка</b>(a + b)² ≠ a² + b². Проверка: (2 + 3)² = 25, а 4 + 9 = 13.</div>`};

/* ---------- генераторы ---------- */
const gens=[];
const G=(lvl,make,star)=>gens.push({lvl,make,star});
const sq2=v=>v+'²',cu=v=>v+'³';

/* L0 — квадрат суммы */
G(0,()=>{const n=R(2,9),v=pick(VARS);
const c=P([[1,sq2(v)],[2*n,v],[n*n,'']]);
const o=mk(c,[P([[1,sq2(v)],[n*n,'']]),P([[1,sq2(v)],[n,v],[n*n,'']]),P([[1,sq2(v)],[2*n,v],[2*n,'']])]);
return {type:'choice',q:`Раскрой скобки: ${M(`(${v} + ${n})²`)}.`,opts:o.opts,ans:o.ans,
hint:'Квадрат первого + удвоенное произведение + квадрат второго.',
short:`${v}² + 2 · ${v} · ${n} + ${n}² = ${c}.`,
explain:`Формула: (a + b)² = a² + <b>2ab</b> + b², здесь a = ${v}, b = ${n}.<br>• a² = ${v}²<br>• 2ab = 2 · ${v} · ${n} = ${2*n}${v}<br>• b² = ${n}² = ${n*n}<br>Ответ: <b>${c}</b>.<div class="box err"><b>Ловушка</b>«${P([[1,sq2(v)],[n*n,'']])}» — потеряли удвоенное произведение. Это самая частая ошибка: (a + b)² ≠ a² + b².</div>`,
explain2:`Распиши квадрат как умножение двух скобок и умножь «каждый на каждого»:<br>(${v} + ${n})(${v} + ${n}) = ${v}·${v} + ${v}·${n} + ${n}·${v} + ${n}·${n} = ${v}² + ${n}${v} + ${n}${v} + ${n*n} = ${c}.<br>Видишь — слагаемое ${n}${v} появляется <b>два раза</b>, поэтому ${2*n}${v}.<br>Проверка числом: при ${v} = 1 слева (1 + ${n})² = ${(1+n)**2}, справа 1 + ${2*n} + ${n*n} = ${1+2*n+n*n} ✅.`};});
G(0,()=>{const m=R(2,5),n=R(1,7),v=pick(VARS);
const c=P([[m*m,sq2(v)],[2*m*n,v],[n*n,'']]);
const o=mk(c,[P([[m*m,sq2(v)],[n*n,'']]),P([[m,sq2(v)],[2*m*n,v],[n*n,'']]),P([[m*m,sq2(v)],[m*n,v],[n*n,'']])]);
return {type:'choice',q:`Раскрой скобки: ${M(`(${B(m,v,n)})²`)}.`,opts:o.opts,ans:o.ans,
short:`(${m}${v})² + 2 · ${m}${v} · ${n} + ${n}² = ${c}.`,
explain:`a = ${m}${v}, b = ${n}.<br>• a² = (${m}${v})² = ${m}² · ${v}² = ${m*m}${v}² — в квадрат возводим <b>и число ${m}</b>, и букву!<br>• 2ab = 2 · ${m}${v} · ${n} = ${2*m*n}${v}<br>• b² = ${n*n}<br>Ответ: <b>${c}</b>.<div class="box err"><b>Ловушки</b>«${P([[m,sq2(v)],[2*m*n,v],[n*n,'']])}» — забыли возвести ${m} в квадрат.<br>«${P([[m*m,sq2(v)],[m*n,v],[n*n,'']])}» — забыли удвоить произведение.</div>`,
explain2:`Проверка подстановкой: пусть ${v} = 1. Слева: (${m} + ${n})² = ${(m+n)**2}. Правильный ответ даёт ${m*m} + ${2*m*n} + ${n*n} = ${m*m+2*m*n+n*n} ✅. А вариант с ${m}${v}² дал бы ${m} + ${2*m*n} + ${n*n} = ${m+2*m*n+n*n} ❌. Подстановка числа — лучший способ поймать свою ошибку.`};});
G(0,()=>{let a,b;do{a=R(2,9);b=R(2,9);}while(a===b);
return {type:'num',q:`Вычисли ${M(`(${a} + ${b})² − (${a}² + ${b}²)`)}.`,ans:2*a*b,
hint:'Посчитай обе части отдельно. Разница не случайна!',
short:`${(a+b)**2} − ${a*a+b*b} = ${2*a*b} = 2 · ${a} · ${b}.`,
explain:`Считаем по порядку:<br>(${a} + ${b})² = ${a+b}² = ${(a+b)**2};<br>${a}² + ${b}² = ${a*a} + ${b*b} = ${a*a+b*b};<br>разность: ${(a+b)**2} − ${a*a+b*b} = <b>${2*a*b}</b>.<br>Заметь: ${2*a*b} = 2 · ${a} · ${b} — это <b>удвоенное произведение</b> 2ab. Именно его «теряют», когда пишут (a + b)² = a² + b².`,
explain2:`По формуле: (${a} + ${b})² = ${a}² + 2 · ${a} · ${b} + ${b}². Если вычесть ${a}² + ${b}², останется только 2 · ${a} · ${b} = ${2*a*b}. На картинке с квадратом это два прямоугольника ${a} × ${b}: ${a*b} + ${a*b} = ${2*a*b}.`};});
G(0,()=>{const m=R(1,4),n=R(2,9),v=pick(VARS);
return {type:'num',q:`Какое число нужно вписать вместо □, чтобы равенство было верным?<br>${M(`(${B(m,v,n)})² = ${P([[m*m,sq2(v)]])} + □${v} + ${n*n}`)}`,ans:2*m*n,
hint:'Посередине стоит удвоенное произведение.',
short:`2 · ${m===1?'':m}${v} · ${n} = ${2*m*n}${v}.`,
explain:`Средний член квадрата суммы — <b>удвоенное произведение</b> 2ab, где a = ${m===1?'':m}${v}, b = ${n}.<br>2 · ${m===1?'':m}${v} · ${n} = ${2*m*n}${v}. В □ пишем <b>${2*m*n}</b>.<div class="box err"><b>Ловушка</b>Не ${m*n} — удвоить обязательно!</div>`,
explain2:`Раскрой (${B(m,v,n)})(${B(m,v,n)}): два «перекрёстных» произведения ${m===1?'':m}${v} · ${n} = ${m*n}${v} и ${n} · ${m===1?'':m}${v} = ${m*n}${v}. Вместе ${m*n} + ${m*n} = ${2*m*n}.`};});

/* L1 — квадрат разности */
G(1,()=>{const n=R(2,9),v=pick(VARS);
const c=P([[1,sq2(v)],[-2*n,v],[n*n,'']]);
const o=mk(c,[P([[1,sq2(v)],[-n*n,'']]),P([[1,sq2(v)],[-2*n,v],[-n*n,'']]),P([[1,sq2(v)],[2*n,v],[n*n,'']])]);
return {type:'choice',q:`Раскрой скобки: ${M(`(${v} − ${n})²`)}.`,opts:o.opts,ans:o.ans,
hint:'Знаки в квадрате разности: + − +.',
short:`${v}² − 2 · ${v} · ${n} + ${n}² = ${c}.`,
explain:`Формула: (a − b)² = a² − 2ab + b², a = ${v}, b = ${n}.<br>${v}² − 2 · ${v} · ${n} + ${n}² = <b>${c}</b>.<br>• «${P([[1,sq2(v)],[-n*n,'']])}» — это разность квадратов, другая формула; потеряно −${2*n}${v}.<br>• «… − ${n*n}» в конце — неверно: (−${n})² = +${n*n}, квадрат всегда с плюсом.<br>• «+ ${2*n}${v}» — это квадрат суммы, знак перепутан.`,
explain2:`Можно свести к квадрату суммы: ${v} − ${n} = ${v} + (−${n}). Тогда 2 · ${v} · (−${n}) = −${2*n}${v}, а (−${n})² = ${n*n}. Отсюда ${c}.<br>Проверка при ${v} = 0: (0 − ${n})² = ${n*n}, и в ответе при ${v} = 0 остаётся ${n*n} ✅ (а не −${n*n}).`};});
G(1,()=>{let m,n;do{m=R(1,5);n=R(1,5);}while(m===n);const [a,b]=pick([['a','b'],['x','y'],['m','n']]);
const mm=m===1?'':m,nn=n===1?'':n;
const c=P([[m*m,a+'²'],[-2*m*n,a+b],[n*n,b+'²']]);
const o=mk(c,[P([[m*m,a+'²'],[-n*n,b+'²']]),P([[m*m,a+'²'],[-m*n,a+b],[n*n,b+'²']]),P([[m*m,a+'²'],[-2*m*n,a+b],[-n*n,b+'²']])]);
return {type:'choice',q:`Раскрой скобки: ${M(`(${mm}${a} − ${nn}${b})²`)}.`,opts:o.opts,ans:o.ans,
short:`${m===1?a:`(${m}${a})`}² − 2 · ${mm}${a} · ${nn}${b} + ${n===1?b:`(${n}${b})`}² = ${c}.`,
explain:`Первое — ${mm}${a}, второе — ${nn}${b}.<br>• квадрат первого: ${m===1?a:`(${m}${a})`}² = ${m*m===1?'':m*m}${a}²<br>• удвоенное произведение: 2 · ${mm}${a} · ${nn}${b} = ${2*m*n}${a}${b} (со знаком минус)<br>• квадрат второго: ${n===1?b:`(${n}${b})`}² = ${n*n===1?'':n*n}${b}²<br>Ответ: <b>${c}</b>.`,
explain2:`Проверка подстановкой ${a} = 1, ${b} = 1: слева (${m} − ${n})² = ${(m-n)**2}. В правильном ответе ${m*m} − ${2*m*n} + ${n*n} = ${(m-n)**2} ✅. Вариант без удвоенного произведения дал бы ${m*m-n*n} — не совпадает.`};});
G(1,()=>{const m=R(2,5),n=R(2,9),v=pick(VARS);
return {type:'num',q:`Какое число пропущено?<br>${M(`(${m}${v} − □)² = ${P([[m*m,sq2(v)],[-2*m*n,v],[n*n,'']])}`)}`,ans:n,
hint:`Последнее слагаемое ${n*n} — это квадрат пропущенного числа. Проверь по среднему члену.`,
short:`□² = ${n*n} и 2 · ${m}${v} · ${n} = ${2*m*n}${v} → □ = ${n}.`,
explain:`В (a − b)² последний член — b². Здесь b² = ${n*n}, значит b = ${n}.<br>Проверим по среднему члену: 2 · ${m}${v} · ${n} = ${2*m*n}${v} ✅ — совпадает.<br>Ответ: <b>${n}</b>.`,
explain2:`Можно идти от среднего члена: 2ab = ${2*m*n}${v}, a = ${m}${v}, значит b = ${2*m*n} : (2 · ${m}) = ${n}. Оба способа дают ${n} — значит, ответ верный.`};});

/* L2 — разность квадратов */
G(2,()=>{const n=R(2,12),v=pick(VARS);
const c=P([[1,sq2(v)],[-n*n,'']]);
const o=mk(c,[P([[1,sq2(v)],[n*n,'']]),P([[1,sq2(v)],[-2*n,v],[-n*n,'']]),P([[1,sq2(v)],[-2*n,'']])]);
return {type:'choice',q:`Выполни умножение: ${M(`(${v} − ${n})(${v} + ${n})`)}.`,opts:o.opts,ans:o.ans,
short:`(a − b)(a + b) = a² − b² = ${c}.`,
explain:`Это формула разности квадратов: (a − b)(a + b) = a² − b².<br>a = ${v}, b = ${n} → ${v}² − ${n}² = <b>${c}</b>.<br>• «+ ${n*n}» — неверный знак: в формуле минус.<br>• «− ${2*n}» — квадрат перепутали с умножением на 2.`,
explain2:`Раскроем скобки «каждый на каждый»: ${v}·${v} + ${n}${v} − ${n}${v} − ${n*n}. Средние слагаемые +${n}${v} и −${n}${v} взаимно уничтожаются — как шаг вперёд и шаг назад. Остаётся ${c}.`};});
G(2,()=>{let m,n;do{m=R(1,5);n=R(2,9);}while(H.gcd(m,n)!==1);const v=pick(VARS);const mv=(m===1?'':m)+v;
const c=`(${mv} − ${n})(${mv} + ${n})`;
const o=mk(c,[`(${mv} − ${n})²`,m>1?`(${m*m}${v} − ${n})(${m*m}${v} + ${n})`:`(${v} − ${n*n})(${v} + ${n*n})`,`(${mv} + ${n})²`]);
return {type:'choice',q:`Разложи на множители: ${M(P([[m*m,sq2(v)],[-n*n,'']]))}.`,opts:o.opts.map(M),ans:o.ans,
hint:'Представь оба слагаемых как квадраты.',
short:`${P([[m*m,sq2(v)]])} = (${mv})², ${n*n} = ${n}² → ${c}.`,
explain:`1) Оба слагаемых — квадраты: ${P([[m*m,sq2(v)]])} = (${mv})², ${n*n} = ${n}².<br>2) Разность квадратов: a² − b² = (a − b)(a + b), a = ${mv}, b = ${n}.<br>Ответ: <b>${c}</b>.<br>• (${mv} − ${n})² — это квадрат разности, при раскрытии появится −${2*m*n}${v}, которого нет.${m>1?`<br>• ${m*m}${v} в скобке — забыли, что ${m*m}${v}² = (${m}${v})², а не (${m*m}${v})².`:''}`,
explain2:`Проверь умножением: (${mv} − ${n})(${mv} + ${n}) = (${mv})² − ${n}² = ${P([[m*m,sq2(v)],[-n*n,'']])} ✅. Разложение и раскрытие — это одна формула, прочитанная в разные стороны.`};});
G(2,()=>{const shift=Math.random()<0.5,n=R(1,9),p=R(1,6);
const ans=shift?[p-n,p+n]:[-n,n];const lhs=shift?`(x − ${p})² − ${n*n} = 0`:`x² − ${n*n} = 0`;
return {type:'set',q:`Реши уравнение ${M(lhs)}. Запиши все корни.`,ans,ph:'например: −3, 3',keys:['−','∅'],
hint:'Разложи левую часть на множители по формуле разности квадратов.',
short:shift?`(x − ${p} − ${n})(x − ${p} + ${n}) = 0 → x = ${N(p+n)} или x = ${N(p-n)}.`:`(x − ${n})(x + ${n}) = 0 → x = ±${n}.`,
explain:shift?`Разность квадратов: (x − ${p})² − ${n}² = (x − ${p} − ${n})(x − ${p} + ${n}) = (x − ${p+n})(${P([[1,'x'],[n-p,'']])}).<br>Произведение равно нулю, когда один из множителей равен нулю:<br>x − ${p+n} = 0 → x = ${p+n}; ${P([[1,'x'],[n-p,'']])} = 0 → x = ${N(p-n)}.<br>Ответ: <b>${N(p-n)}; ${N(p+n)}</b>.`:`Разность квадратов: x² − ${n*n} = (x − ${n})(x + ${n}).<br>Произведение равно нулю, когда один из множителей равен нулю: x = ${n} или x = −${n}.<br>Ответ: <b>−${n}; ${n}</b>.<div class="box err"><b>Ловушка</b>Не теряй отрицательный корень: (−${n})² − ${n*n} = 0 ✅.</div>`,
explain2:shift?`Другой путь: (x − ${p})² = ${n*n}, значит x − ${p} = ${n} или x − ${p} = −${n}. Отсюда x = ${p+n} или x = ${N(p-n)}. Проверка: (${p+n} − ${p})² = ${n*n} ✅, (${N(p-n)} − ${p})² = (−${n})² = ${n*n} ✅.`:`Можно перенести: x² = ${n*n}. Какие числа в квадрате дают ${n*n}? ${n} и −${n}. Проверь подстановкой оба.`};});

/* L3 — устный счёт */
G(3,()=>{const base=pick([20,30,40,50,60,70,80,90,100,200]),d=pick([-2,-1,1,2,3]);const x=base+d;const ans=x*x;
const op=d>0?'+':'−',ad=Math.abs(d);
return {type:'num',q:`Вычисли устно, используя формулу: ${M(`${x}²`)}.`,ans,
hint:`${x} = ${base} ${op} ${ad}.`,
short:`(${base} ${op} ${ad})² = ${base*base} ${op} ${2*base*ad} + ${ad*ad} = ${ans}.`,
explain:`Представим ${x} как «круглое ${op} немного»: ${x} = ${base} ${op} ${ad}.<br>(${base} ${op} ${ad})² = ${base}² ${op} 2 · ${base} · ${ad} + ${ad}² = ${base*base} ${op} ${2*base*ad} + ${ad*ad} = <b>${ans}</b>.<div class="box err"><b>Ловушка</b>${base*base} ${op} ${ad*ad} = ${d>0?base*base+ad*ad:base*base-ad*ad} — неверно, потеряно удвоенное произведение ${2*base*ad}.</div>`,
explain2:`Проверим столбиком в уме: ${x} · ${x} = ${x} · ${base} ${op} ${x} · ${ad} = ${x*base} ${op} ${x*ad} = ${ans}. Совпало — но через формулу гораздо быстрее, потому что ${base}² считается мгновенно.`};});
G(3,()=>{const base=pick([20,30,40,50,60,70,80,90,100]),d=R(1,3);const a=base+d,b=base-d;
return {type:'num',q:`Вычисли устно: ${M(`${a} · ${b}`)}.`,ans:a*b,
hint:`Оба числа на ${d} отличаются от ${base}.`,
short:`(${base} + ${d})(${base} − ${d}) = ${base*base} − ${d*d} = ${a*b}.`,
explain:`Заметим: ${a} = ${base} + ${d}, ${b} = ${base} − ${d}. Это разность квадратов:<br>(${base} + ${d})(${base} − ${d}) = ${base}² − ${d}² = ${base*base} − ${d*d} = <b>${a*b}</b>.`,
explain2:`Представь прямоугольник ${a} × ${b}. Если отрезать от длинной стороны полоску шириной ${d} и приставить к короткой, почти получится квадрат ${base} × ${base} — только в углу не хватит кусочка ${d} × ${d}. Поэтому ${base*base} − ${d*d} = ${a*b}.`};});
G(3,()=>{const d=pick([2,4,6,10]),s=pick([100,200,160,120,80,60,140]);const a=(s+d)/2,b=(s-d)/2;
if(!Number.isInteger(a))return null;
return {type:'num',q:`Вычисли: ${M(`${a}² − ${b}²`)}.`,ans:a*a-b*b,
hint:'Не возводи в квадрат! Используй разность квадратов.',
short:`(${a} − ${b})(${a} + ${b}) = ${d} · ${s} = ${d*s}.`,
explain:`a² − b² = (a − b)(a + b):<br>${a}² − ${b}² = (${a} − ${b})(${a} + ${b}) = ${d} · ${s} = <b>${d*s}</b>.<br>Удобно, потому что сумма ${a} + ${b} = ${s} — круглое число.`,
explain2:`Проверка «в лоб»: ${a}² = ${a*a}, ${b}² = ${b*b}, разность ${a*a} − ${b*b} = ${a*a-b*b}. Ответ тот же, но считать дольше и легче ошибиться.`};});
G(3,()=>{const s=pick([40,50,60,70,80,90,100]);const b=R(11,s/2-2),a=s-b;
return {type:'num',q:`Вычисли: ${M(`(${a}² − ${b}²) : ${s}`)}.`,ans:a-b,
hint:`Разложи ${a}² − ${b}² на множители. Ничего не напоминает число ${s}?`,
short:`(${a} − ${b})(${a} + ${b}) : ${s} = ${a-b} · ${s} : ${s} = ${a-b}.`,
explain:`${a}² − ${b}² = (${a} − ${b})(${a} + ${b}) = ${a-b} · ${s}.<br>Делим на ${s}: ${a-b} · ${s} : ${s} = <b>${a-b}</b>.`,
explain2:`Посмотри: ${a} + ${b} = ${s} — именно на это число мы делим. Значит, после разложения множитель ${s} просто сокращается, и остаётся ${a} − ${b} = ${a-b}.`};});

/* L4 — разложение, полный квадрат */
G(4,()=>{const n=R(2,9),v=pick(VARS),plus=Math.random()<0.5,s=plus?1:-1;
const e=P([[1,sq2(v)],[s*2*n,v],[n*n,'']]);const c=`(${v} ${plus?'+':'−'} ${n})²`;
const o=mk(c,[`(${v} ${plus?'−':'+'} ${n})²`,`(${v} ${plus?'+':'−'} ${2*n})²`,`(${v} − ${n})(${v} + ${n})`]);
return {type:'choice',q:`Представь в виде квадрата двучлена: ${M(e)}.`,opts:o.opts.map(M),ans:o.ans,
short:`${v}² ${plus?'+':'−'} 2 · ${v} · ${n} + ${n}² = ${c}.`,
explain:`1) Квадраты: ${v}² = (${v})², ${n*n} = ${n}².<br>2) Проверяем середину: 2 · ${v} · ${n} = ${2*n}${v} ✅, знак «${plus?'+':'−'}».<br>3) Значит, это квадрат ${plus?'суммы':'разности'}: <b>${c}</b>.<br>• (${v} ${plus?'+':'−'} ${2*n})² — в скобке не ${2*n}, а ${n}: ${2*n} — это уже удвоенное число.<br>• (${v} − ${n})(${v} + ${n}) = ${v}² − ${n*n} — среднего члена нет.`,
explain2:`Проверка раскрытием: ${c} = ${v}² ${plus?'+':'−'} ${2*n}${v} + ${n*n} ✅. Подсказка по знаку: знак в скобке — такой же, как знак перед ${2*n}${v}.`};});
G(4,()=>{const n=R(2,9),v=pick(VARS),plus=Math.random()<0.5,s=plus?1:-1;
const good=P([[1,sq2(v)],[s*2*n,v],[n*n,'']]);
const o=mk(good,[P([[1,sq2(v)],[s*n,v],[n*n,'']]),P([[1,sq2(v)],[s*2*n,v],[-n*n,'']]),P([[1,sq2(v)],[s*2*n,v],[2*n,'']])]);
return {type:'choice',q:`Какой из трёхчленов является <b>полным квадратом</b>?`,opts:o.opts.map(M),ans:o.ans,
short:`${good} = (${v} ${plus?'+':'−'} ${n})².`,
explain:`Полный квадрат: a² ± 2ab + b², где оба крайних — квадраты <b>со знаком плюс</b>, а середина — удвоенное произведение.<br>• <b>${good}</b> = (${v} ${plus?'+':'−'} ${n})² ✅.<br>• ${P([[1,sq2(v)],[s*n,v],[n*n,'']])} — посередине должно быть ${2*n}${v}, а стоит ${n}${v}.<br>• ${P([[1,sq2(v)],[s*2*n,v],[-n*n,'']])} — −${n*n} не может быть квадратом (квадрат ≥ 0).<br>• ${P([[1,sq2(v)],[s*2*n,v],[2*n,'']])} — ${2*n} не равно ${n}² = ${n*n}.`,
explain2:`Подставь ${v} = 0: у полного квадрата (0 ${plus?'+':'−'} ${n})² = ${n*n} — свободный член должен быть ровно ${n*n}. Подставь ${v} = 1: (1 ${plus?'+':'−'} ${n})² = ${(1+s*n)**2}, и только у правильного варианта 1 ${plus?'+':'−'} ${2*n} + ${n*n} = ${(1+s*n)**2}.`};});
G(4,()=>{const n=R(2,10),v=pick(VARS),plus=Math.random()<0.5;
return {type:'num',q:`Какое число нужно поставить вместо □, чтобы получился полный квадрат?<br>${M(`${v}² ${plus?'+':'−'} ${2*n}${v} + □`)}`,ans:n*n,
hint:`${2*n}${v} = 2 · ${v} · ?`,
short:`${2*n}${v} = 2 · ${v} · ${n} → □ = ${n}² = ${n*n}.`,
explain:`Средний член — удвоенное произведение: ${2*n}${v} = 2 · ${v} · <b>${n}</b>. Значит, второе число в скобке — ${n}.<br>Последний член — его квадрат: ${n}² = <b>${n*n}</b>.<br>Получится ${v}² ${plus?'+':'−'} ${2*n}${v} + ${n*n} = (${v} ${plus?'+':'−'} ${n})².<div class="box err"><b>Ловушка</b>Ответ ${2*n} или ${n} — нет: нужен <b>квадрат половины</b> коэффициента: (${2*n} : 2)² = ${n*n}.</div>`,
explain2:`Правило «половина в квадрате»: коэффициент при ${v} — это ${2*n}. Берём половину: ${n}. Возводим в квадрат: ${n*n}. Проверь: (${v} ${plus?'+':'−'} ${n})² = ${v}² ${plus?'+':'−'} ${2*n}${v} + ${n*n} ✅.`};});
G(4,()=>{const m=R(2,4);let n;do{n=R(1,7);}while(H.gcd(m,n)!==1);const v=pick(VARS);
const e=P([[m*m,sq2(v)],[2*m*n,v],[n*n,'']]);const c=`(${m}${v} + ${n})²`;
const o=mk(c,[`(${m*m}${v} + ${n})²`,`(${m}${v} + ${n*n})²`,`(${m}${v} + ${n})(${m}${v} − ${n})`]);
return {type:'choice',q:`Разложи на множители: ${M(e)}.`,opts:o.opts.map(M),ans:o.ans,
short:`${m*m}${v}² = (${m}${v})², ${n*n} = ${n}², 2 · ${m}${v} · ${n} = ${2*m*n}${v} → ${c}.`,
explain:`1) ${m*m}${v}² = (${m}${v})² — это квадрат ${m}${v} (а не ${m*m}${v}!).<br>2) ${n*n} = ${n}².<br>3) Середина: 2 · ${m}${v} · ${n} = ${2*m*n}${v} ✅.<br>Ответ: <b>${c}</b>.<br>• (${m*m}${v} + ${n})² даст ${m**4}${v}² — слишком много.<br>• (${m}${v} + ${n*n})² даст ${n**4} в конце.`,
explain2:`Проверка подстановкой ${v} = 1: ${m*m} + ${2*m*n} + ${n*n} = ${(m+n)**2}, и (${m} + ${n})² = ${(m+n)**2} ✅. Для варианта (${m*m}${v} + ${n})²: (${m*m} + ${n})² = ${(m*m+n)**2} ❌.`};});

/* L5 — кубы суммы и разности */
G(5,()=>{const n=R(2,4),v=pick(['x','a','y']);
const c=P([[1,cu(v)],[3*n,sq2(v)],[3*n*n,v],[n**3,'']]);
const o=mk(c,[P([[1,cu(v)],[n**3,'']]),P([[1,cu(v)],[n,sq2(v)],[n*n,v],[n**3,'']]),P([[1,cu(v)],[3*n,sq2(v)],[3*n,v],[n**3,'']])]);
return {type:'choice',q:`Раскрой скобки: ${M(`(${v} + ${n})³`)}.`,opts:o.opts,ans:o.ans,
hint:'Коэффициенты 1, 3, 3, 1.',
short:`${v}³ + 3·${v}²·${n} + 3·${v}·${n}² + ${n}³ = ${c}.`,
explain:`Формула: (a + b)³ = a³ + 3a²b + 3ab² + b³, a = ${v}, b = ${n}.<br>• a³ = ${v}³<br>• 3a²b = 3 · ${v}² · ${n} = ${3*n}${v}²<br>• 3ab² = 3 · ${v} · ${n*n} = ${3*n*n}${v}<br>• b³ = ${n**3}<br>Ответ: <b>${c}</b>.<div class="box err"><b>Ловушки</b>«${P([[1,cu(v)],[n**3,'']])}» — (a + b)³ ≠ a³ + b³.<br>«… + ${3*n}${v} …» — забыли возвести ${n} в квадрат в слагаемом 3ab².</div>`,
explain2:`Можно раскрыть по шагам: (${v} + ${n})³ = (${v} + ${n})² · (${v} + ${n}) = (${v}² + ${2*n}${v} + ${n*n})(${v} + ${n}) = ${v}³ + ${n}${v}² + ${2*n}${v}² + ${2*n*n}${v} + ${n*n}${v} + ${n**3} = ${c}.<br>Проверка при ${v} = 1: (1 + ${n})³ = ${(1+n)**3}, и 1 + ${3*n} + ${3*n*n} + ${n**3} = ${1+3*n+3*n*n+n**3} ✅.`};});
G(5,()=>{const n=R(1,4),v=pick(['x','a','y']);
const c=P([[1,cu(v)],[-3*n,sq2(v)],[3*n*n,v],[-(n**3),'']]);
const o=mk(c,[P([[1,cu(v)],[-(n**3),'']]),P([[1,cu(v)],[-3*n,sq2(v)],[-3*n*n,v],[-(n**3),'']]),P([[1,cu(v)],[-3*n,sq2(v)],[3*n*n,v],[n**3,'']])]);
return {type:'choice',q:`Раскрой скобки: ${M(`(${v} − ${n})³`)}.`,opts:o.opts,ans:o.ans,
hint:'Знаки в кубе разности чередуются: + − + −.',
short:`${v}³ − ${3*n}${v}² + ${3*n*n}${v} − ${n**3}.`,
explain:`(a − b)³ = a³ − 3a²b + 3ab² − b³, a = ${v}, b = ${n}:<br>${v}³ − 3 · ${v}² · ${n} + 3 · ${v} · ${n*n} − ${n**3} = <b>${c}</b>.<br>Знаки <b>чередуются</b>: + − + −. Третье слагаемое с плюсом, потому что (−${n})² = ${n*n} > 0, а последнее с минусом: (−${n})³ = −${n**3}.`,
explain2:`Запиши ${v} − ${n} = ${v} + (−${n}) и подставь в куб суммы: ${v}³ + 3${v}²(−${n}) + 3${v}(−${n})² + (−${n})³. Чётная степень минуса — плюс, нечётная — минус. Отсюда знаки + − + −.<br>Проверка при ${v} = 0: (−${n})³ = −${n**3} — свободный член −${n**3} ✅.`};});
G(5,()=>{const n=R(2,6),which=pick(['x','x2','c']);const v='x';
const coef={x:3*n*n,x2:3*n,c:n**3}[which];
const label={x:`коэффициент при ${v}`,x2:`коэффициент при ${v}²`,c:'свободный член (число без буквы)'}[which];
return {type:'num',q:`Не раскрывая всех скобок, найди в многочлене ${M(`(${v} + ${n})³`)} ${label}.`,ans:coef,
hint:'(a + b)³ = a³ + 3a²b + 3ab² + b³.',
short:`${which==='x'?`3ab² = 3 · ${v} · ${n}² = ${3*n*n}${v}`:which==='x2'?`3a²b = 3 · ${v}² · ${n} = ${3*n}${v}²`:`b³ = ${n}³ = ${n**3}`}.`,
explain:`(${v} + ${n})³ = ${v}³ + 3 · ${v}² · ${n} + 3 · ${v} · ${n}² + ${n}³ = ${P([[1,cu(v)],[3*n,sq2(v)],[3*n*n,v],[n**3,'']])}.<br>Нужный член: ${which==='x'?`${3*n*n}${v}`:which==='x2'?`${3*n}${v}²`:`${n**3}`}. Ответ: <b>${coef}</b>.`,
explain2:`Вспомни картинку: степень ${v} уменьшается 3, 2, 1, 0, а степень ${n} растёт 0, 1, 2, 3, коэффициенты 1, 3, 3, 1. ${which==='x'?`При ${v}¹ стоит 3 · ${n}² = ${3*n*n}.`:which==='x2'?`При ${v}² стоит 3 · ${n}¹ = ${3*n}.`:`Без ${v} стоит 1 · ${n}³ = ${n**3}.`}`};});

/* L6 — сумма и разность кубов */
G(6,()=>{const n=R(2,5),v=pick(['x','a','y']);
const c=`(${v} − ${n})(${P([[1,sq2(v)],[n,v],[n*n,'']])})`;
const o=mk(c,[`(${v} − ${n})(${P([[1,sq2(v)],[2*n,v],[n*n,'']])})`,`(${v} − ${n})(${P([[1,sq2(v)],[-n,v],[n*n,'']])})`,`(${v} − ${n})³`]);
return {type:'choice',q:`Разложи на множители: ${M(`${v}³ − ${n**3}`)}.`,opts:o.opts.map(M),ans:o.ans,
hint:`${n**3} = ${n}³. Разность кубов: a³ − b³ = (a − b)(a² + ab + b²).`,
short:`${v}³ − ${n}³ = ${c}.`,
explain:`1) ${n**3} = ${n}³, так что это разность кубов: a = ${v}, b = ${n}.<br>2) a³ − b³ = (a − b)(a² <b>+ ab</b> + b²) = <b>${c}</b>.<br>• С ${2*n}${v} посередине — это (${v} + ${n})², а в формуле кубов «неполный квадрат»: просто ab, без двойки.<br>• С −${n}${v} — перепутан знак: у разности кубов во второй скобке посередине <b>плюс</b>.<br>• (${v} − ${n})³ ≠ ${v}³ − ${n**3}: при раскрытии появятся ещё члены с ${v}² и ${v}.`,
explain2:`Проверим раскрытием: (${v} − ${n})(${v}² + ${n}${v} + ${n*n}) = ${v}³ + ${n}${v}² + ${n*n}${v} − ${n}${v}² − ${n*n}${v} − ${n**3} = ${v}³ − ${n**3} ✅. Все средние члены сократились — именно для этого во второй скобке ${n}${v}, а не ${2*n}${v}.`};});
G(6,()=>{let m,n;do{m=R(1,3);n=R(1,5);}while(m===n||(m===1&&n===1));const v=pick(['a','x','b']);const mv=(m===1?'':m)+v;
const sq=P([[m*m,sq2(v)],[-m*n,v],[n*n,'']]);
const c=`(${mv} + ${n})(${sq})`;
const o=mk(c,[`(${mv} + ${n})(${P([[m*m,sq2(v)],[m*n,v],[n*n,'']])})`,`(${mv} + ${n})(${P([[m*m,sq2(v)],[-2*m*n,v],[n*n,'']])})`,`(${mv} + ${n})³`]);
return {type:'choice',q:`Разложи на множители: ${M(P([[m**3,cu(v)],[n**3,'']]))}.`,opts:o.opts.map(M),ans:o.ans,
hint:'a³ + b³ = (a + b)(a² − ab + b²).',
short:`${m===1?v:`(${mv})`}³ + ${n}³ = ${c}.`,
explain:`1) ${P([[m**3,cu(v)]])} = ${m===1?v:`(${mv})`}³, ${n**3} = ${n}³.<br>2) Сумма кубов: a³ + b³ = (a + b)(a² <b>− ab</b> + b²), a = ${mv}, b = ${n}:<br>a² = ${P([[m*m,sq2(v)]])}, ab = ${P([[m*n,v]])}, b² = ${n*n}.<br>Ответ: <b>${c}</b>.<br>Правило знаков: в первой скобке тот же знак (+), посередине второй — противоположный (−), в конце — всегда +.`,
explain2:`Проверка подстановкой ${v} = 1: слева ${m**3} + ${n**3} = ${m**3+n**3}. Справа (${m} + ${n})(${m*m} − ${m*n} + ${n*n}) = ${m+n} · ${m*m-m*n+n*n} = ${(m+n)*(m*m-m*n+n*n)} ✅.`};});
G(6,()=>{const a=R(11,30),b=R(2,a-3);
return {type:'num',q:`Вычисли: ${M(`(${a}³ − ${b}³) : (${a}² + ${a} · ${b} + ${b}²)`)}.`,ans:a-b,
hint:'Узнаёшь неполный квадрат из формулы разности кубов?',
short:`${a}³ − ${b}³ = (${a} − ${b})(${a}² + ${a}·${b} + ${b}²), после деления остаётся ${a-b}.`,
explain:`По формуле разности кубов: ${a}³ − ${b}³ = (${a} − ${b})(${a}² + ${a} · ${b} + ${b}²).<br>Вторая скобка в точности совпадает с делителем — она сокращается.<br>Остаётся ${a} − ${b} = <b>${a-b}</b>.`,
explain2:`Можно и посчитать: ${a}³ = ${a**3}, ${b}³ = ${b**3}, разность ${a**3-b**3}; делитель ${a*a} + ${a*b} + ${b*b} = ${a*a+a*b+b*b}; ${a**3-b**3} : ${a*a+a*b+b*b} = ${a-b}. Тот же ответ, но через формулу — без больших чисел.`};});

/* L7 — выделение полного квадрата */
const minPar=()=>{let p,c;do{p=pick([-5,-4,-3,-2,-1,1,2,3,4,5,6]);c=R(-6,40);}while(c===0||c===p*p);return {p,c,m:c-p*p};};
G(7,()=>{const {p,c,m}=minPar();const e=P([[1,'x²'],[-2*p,'x'],[c,'']]);const sb=`(x ${p>0?'−':'+'} ${Math.abs(p)})²`;
return {type:'num',q:`Найди наименьшее значение выражения ${M(e)}.`,ans:m,
hint:`Выдели полный квадрат: ${sb} = ?`,
short:`${e} = ${sb} ${m<0?'−':'+'} ${Math.abs(m)}; минимум ${N(m)} при x = ${N(p)}.`,
explain:`1) Берём половину коэффициента при x: ${N(-2*p)} : 2 = ${N(-p)}. Значит, нужна скобка ${sb} = x² ${p>0?'−':'+'} ${2*Math.abs(p)}x + ${p*p}.<br>2) ${e} = (x² ${p>0?'−':'+'} ${2*Math.abs(p)}x + ${p*p}) − ${p*p} ${c<0?'−':'+'} ${Math.abs(c)} = ${sb} ${m<0?'−':'+'} ${Math.abs(m)}.<br>3) ${sb} ≥ 0, и равно 0 при x = ${N(p)}. Значит, наименьшее значение — <b>${N(m)}</b>.<div class="box err"><b>Ловушка</b>Ответ ${N(c)} неверен: добавив ${p*p}, надо столько же и вычесть.</div>`,
explain2:`Проверь подстановкой: при x = ${N(p)}: ${N(p)}² ${p>0?'−':'+'} ${2*Math.abs(p)} · ${Math.abs(p)} ${c<0?'−':'+'} ${Math.abs(c)} = ${p*p} − ${2*p*p} ${c<0?'−':'+'} ${Math.abs(c)} = ${N(m)}. А при x = ${N(p+1)} получится ${N((p+1)**2-2*p*(p+1)+c)}, при x = ${N(p-1)} — ${N((p-1)**2-2*p*(p-1)+c)}: больше. Меньше ${N(m)} не бывает, потому что ${sb} не бывает отрицательным.`};});
G(7,()=>{const {p,c,m}=minPar();const e=P([[1,'x²'],[-2*p,'x'],[c,'']]);const sb=`(x ${p>0?'−':'+'} ${Math.abs(p)})²`;
return {type:'num',q:`При каком значении x выражение ${M(e)} принимает наименьшее значение?`,ans:p,
hint:'Выдели полный квадрат. Когда квадрат равен нулю?',
short:`${e} = ${sb} ${m<0?'−':'+'} ${Math.abs(m)}; квадрат = 0 при x = ${N(p)}.`,
explain:`Выделяем полный квадрат: ${e} = ${sb} ${m<0?'−':'+'} ${Math.abs(m)}.<br>Наименьшее значение будет, когда ${sb} = 0, то есть x ${p>0?'−':'+'} ${Math.abs(p)} = 0 → <b>x = ${N(p)}</b>.<div class="box err"><b>Ловушка</b>Знак! В скобке «${p>0?'−':'+'} ${Math.abs(p)}», а ответ x = ${N(p)}. Чтобы скобка обнулилась, x должен быть «противоположным» числу в скобке.</div>`,
explain2:`Быстрый способ: для x² + bx + c наименьшее значение при x = −b : 2. Здесь b = ${N(-2*p)}, значит x = ${N(2*p)} : 2 = ${N(p)}. Это середина между точками, где выражение принимает одинаковые значения: например, при x = 0 и x = ${N(2*p)} оно равно ${N(c)}.`};});
G(7,()=>{const {p,c,m}=minPar();const e=P([[1,'x²'],[-2*p,'x'],[c,'']]);const s=p>0?'−':'+',a=Math.abs(p);
const tail=k=>k===0?'':` ${k<0?'−':'+'} ${Math.abs(k)}`;
const cr=`(x ${s} ${a})²${tail(m)}`;
const o=mk(cr,[`(x ${s} ${a})²${tail(c)}`,`(x ${s} ${2*a})²${tail(c-4*p*p)}`,`(x ${s} ${a})²${tail(c+p*p)}`]);
return {type:'choice',q:`Выдели полный квадрат: ${M(e)}.`,opts:o.opts.map(M),ans:o.ans,
short:`(x ${s} ${a})² = x² ${s} ${2*a}x + ${p*p}, поэтому ${e} = ${cr}.`,
explain:`(x ${s} ${a})² = x² ${s} ${2*a}x + ${p*p}. В нашем выражении вместо ${p*p} стоит ${N(c)}, значит:<br>${e} = (x² ${s} ${2*a}x + ${p*p}) ${c-p*p<0?'−':'+'} ${Math.abs(c-p*p)} = <b>${cr}</b>.<br>• «${`(x ${s} ${a})²${tail(c)}`}» — забыли вычесть ${p*p}.<br>• «${`(x ${s} ${a})²${tail(c+p*p)}`}» — вместо вычитания ${p*p} прибавили.<br>• «(x ${s} ${2*a})²» — в скобке половина коэффициента, а не он сам.`,
explain2:`Проверь раскрытием: ${cr} = x² ${s} ${2*a}x + ${p*p}${tail(m)} = ${e} ✅. Если раскрыть неправильный вариант, свободный член не совпадёт.`};});

/* L8 — комбинированные */
G(8,()=>{let a,x;do{a=R(1,5);x=R(-6,9);}while(x===0);const Nn=4*a*x;
return {type:'num',q:`Реши уравнение: ${M(`(x + ${a})² − (x − ${a})² = ${N(Nn)}`)}.`,ans:x,
hint:'Раскрой обе скобки. x² сократится.',
short:`(x + ${a})² − (x − ${a})² = ${4*a}x = ${N(Nn)} → x = ${N(x)}.`,
explain:`(x + ${a})² = x² + ${2*a}x + ${a*a};<br>(x − ${a})² = x² − ${2*a}x + ${a*a};<br>Разность: x² + ${2*a}x + ${a*a} − x² + ${2*a}x − ${a*a} = ${4*a}x (минус перед второй скобкой поменял все её знаки).<br>${4*a}x = ${N(Nn)} → x = ${N(Nn)} : ${4*a} = <b>${N(x)}</b>.`,
explain2:`Короткий путь — разность квадратов: A² − B² = (A − B)(A + B), где A = x + ${a}, B = x − ${a}.<br>A − B = ${2*a}, A + B = 2x. Произведение ${2*a} · 2x = ${4*a}x. Дальше так же: x = ${N(x)}. Проверь: (${N(x)} + ${a})² − (${N(x)} − ${a})² = ${(x+a)**2} − ${(x-a)**2} = ${N(Nn)} ✅.`};});
G(8,()=>{let a,x;do{a=R(1,6);x=R(-5,9);}while(x===0);const Nn=2*a*x+a*a;
return {type:'num',q:`Реши уравнение: ${M(`(x + ${a})² − x² = ${N(Nn)}`)}.`,ans:x,
short:`${2*a}x + ${a*a} = ${N(Nn)} → x = ${N(x)}.`,
explain:`(x + ${a})² − x² = x² + ${2*a}x + ${a*a} − x² = ${2*a}x + ${a*a}.<br>${2*a}x + ${a*a} = ${N(Nn)} → ${2*a}x = ${N(Nn-a*a)} → x = <b>${N(x)}</b>.<div class="box err"><b>Ловушка</b>Если написать (x + ${a})² = x² + ${a*a}, получится ${a*a} = ${N(Nn)} — бессмыслица. Удвоенное произведение ${2*a}x и есть то, ради чего решается уравнение.</div>`,
explain2:`Через разность квадратов: (x + ${a})² − x² = (x + ${a} − x)(x + ${a} + x) = ${a}(2x + ${a}). Значит, ${a}(2x + ${a}) = ${N(Nn)}, 2x + ${a} = ${N(Nn/a)}, x = ${N(x)}. Проверь: (${N(x+a)})² − (${N(x)})² = ${(x+a)**2} − ${x*x} = ${N(Nn)} ✅.`};});
G(8,()=>{const n=R(2,7),v=pick(VARS);
const c=P([[2*n,v],[-2*n*n,'']]);
const o=mk(c,[P([[-2*n,v]]),'0',P([[2*n,v],[2*n*n,'']])]);
return {type:'choice',q:`Упрости: ${M(`(${v} + ${n})(${v} − ${n}) − (${v} − ${n})²`)}.`,opts:o.opts.map(M),ans:o.ans,
short:`${v}² − ${n*n} − ${v}² + ${2*n}${v} − ${n*n} = ${c}.`,
explain:`1) (${v} + ${n})(${v} − ${n}) = ${v}² − ${n*n}.<br>2) (${v} − ${n})² = ${v}² − ${2*n}${v} + ${n*n}.<br>3) Вычитаем, раскрывая скобку с минусом (все знаки меняются!):<br>${v}² − ${n*n} − ${v}² + ${2*n}${v} − ${n*n} = <b>${c}</b>.<br>• «${P([[-2*n,v]])}» — забыли поменять знаки внутри второй скобки.<br>• «0» — решили, что (${v} − ${n})² = ${v}² − ${n*n}.`,
explain2:`Проверка подстановкой ${v} = ${n+1}: (${2*n+1}) · 1 − 1² = ${2*n}. А ${c} при ${v} = ${n+1}: ${2*n*(n+1)} − ${2*n*n} = ${2*n} ✅.`};});
G(8,()=>{const minus=Math.random()<0.4;let a,b;if(minus){a=R(40,99);b=a-pick([10,20,30,40,50]);}else{const s=pick([30,40,50,60,70,80,100]);a=R(Math.ceil(s/2)+1,s-3);b=s-a;}
const ans=minus?(a-b)**2:(a+b)**2;
return {type:'num',q:`Вычисли удобным способом: ${M(`${a}² ${minus?'−':'+'} 2 · ${a} · ${b} + ${b}²`)}.`,ans,
hint:`Это ${minus?'квадрат разности':'квадрат суммы'}, записанный «справа налево».`,
short:`(${a} ${minus?'−':'+'} ${b})² = ${minus?a-b:a+b}² = ${ans}.`,
explain:`Выражение имеет вид a² ${minus?'−':'+'} 2ab + b² = (a ${minus?'−':'+'} b)², где a = ${a}, b = ${b}.<br>(${a} ${minus?'−':'+'} ${b})² = ${minus?a-b:a+b}² = <b>${ans}</b>.`,
explain2:`«В лоб»: ${a}² = ${a*a}, 2 · ${a} · ${b} = ${2*a*b}, ${b}² = ${b*b}; ${a*a} ${minus?'−':'+'} ${2*a*b} + ${b*b} = ${ans}. Тот же ответ, но три больших умножения вместо одного маленького.`};});

/* L9 — ★ */
G(9,()=>{const v=pick([[2,3],[2,4],[3,3]]);const [b,k]=v;
let prod=1;const fs=[];for(let i=0;i<k;i++){const e=2**i;prod*=b**e+1;fs.push(`(${b}${e>1?sup(e):''} + 1)`);}
const E=2**k;const formula=(b**E-1)/(b-1);if(formula!==prod)return null;
return {type:'num',q:`Вычисли: ${M(fs.join(''))}.`,ans:prod,
hint:`Домножь на (${b} − 1)${b-1===1?' = 1':` и потом раздели на ${b-1}`}. Дальше — цепочка разностей квадратов.`,
short:`(${b} − 1) · … = ${b}${sup(E)} − 1, значит ответ ${b===2?`2${sup(E)} − 1`:`(${b}${sup(E)} − 1) : ${b-1}`} = ${prod}.`,
explain:`Хитрость: умножим выражение на (${b} − 1)${b===2?' = 1 (значение не изменится)':` = ${b-1}, а в конце разделим на ${b-1}`}.<br>${range(0,k-1).map(i=>{const e=2**i;return `(${b}${e>1?sup(e):''} − 1)(${b}${e>1?sup(e):''} + 1) = ${b}${sup(2*e)} − 1`;}).join('<br>')}<br>Каждый раз срабатывает разность квадратов, и в конце получается ${b}${sup(E)} − 1 = ${b**E-1}.<br>${b===2?`Ответ: <b>${prod}</b>.`:`Делим на ${b-1}: ${b**E-1} : ${b-1} = <b>${prod}</b>.`}`,
explain2:`Проверка прямым умножением: ${fs.map((f,i)=>b**(2**i)+1).join(' · ')} = ${prod} ✅.<br>Аналогия — «домино»: первая разность (${b} − 1) «сталкивает» первую скобку, получается новая разность, которая сталкивает следующую скобку, и так до конца.`};},true);
G(9,()=>{const E=pick([8,16]);const X=2**E-1;
const divs=E===16?[3,5,15,17,51,85,255,257]:[3,5,15,17,51,85];const non=[7,11,13,19,9];
const ds=sample(divs,3),nd=pick(non);
const opts=shuffle([...ds,nd].map(String));
return {type:'choice',q:`Какое из чисел <b>не является</b> делителем числа ${M(`2${sup(E)} − 1`)}?`,opts,ans:opts.indexOf(String(nd)),
hint:'Разложи 2^'+E+' − 1 по формуле разности квадратов, и ещё раз, и ещё раз.',
short:`2${sup(E)} − 1 = ${E===16?'3 · 5 · 17 · 257':'3 · 5 · 17'}; на ${nd} не делится.`,
explain:`Раскладываем разностью квадратов несколько раз:<br>${E===16?`2${sup(16)} − 1 = (2⁸ − 1)(2⁸ + 1) = (2⁴ − 1)(2⁴ + 1)(2⁸ + 1) = 15 · 17 · 257 = 3 · 5 · 17 · 257.`:`2⁸ − 1 = (2⁴ − 1)(2⁴ + 1) = 15 · 17 = 3 · 5 · 17.`}<br>Делители — это 1, простые множители и их произведения: ${ds.sort((x,y)=>x-y).map(d=>`${d} ✅`).join(', ')}.<br>Числа <b>${nd}</b> среди множителей нет (${nd===9?'9 = 3 · 3, а тройка в разложении только одна':`${nd} — простое число, которого нет в разложении`}). Ответ: <b>${nd}</b>.`,
explain2:`Проверка делением: 2${sup(E)} − 1 = ${X}. ${ds.map(d=>`${X} : ${d} = ${X/d}`).join('; ')} — делится нацело. А ${X} : ${nd} = ${Math.floor(X/nd)} (остаток ${X%nd}).`};},true);
G(9,()=>{let p,q,c,m;do{p=pick([-4,-3,-2,-1,1,2,3,4]);q=pick([-4,-3,-2,-1,1,2,3,4]);c=R(5,40);m=c-p*p-q*q;}while(m<-5||m>15);
const e=P([[1,'x²'],[1,'y²'],[-2*p,'x'],[-2*q,'y'],[c,'']]);
const bx=`(x ${p>0?'−':'+'} ${Math.abs(p)})²`,by=`(y ${q>0?'−':'+'} ${Math.abs(q)})²`;
return {type:'num',q:`Найди наименьшее значение выражения ${M(e)}.`,ans:m,
hint:'Собери отдельно полный квадрат с x и полный квадрат с y.',
short:`${e} = ${bx} + ${by} ${m<0?'−':'+'} ${Math.abs(m)}; минимум ${N(m)}.`,
explain:`Группируем: (x² ${p>0?'−':'+'} ${2*Math.abs(p)}x) + (y² ${q>0?'−':'+'} ${2*Math.abs(q)}y) + ${c}.<br>x² ${p>0?'−':'+'} ${2*Math.abs(p)}x = ${bx} − ${p*p};<br>y² ${q>0?'−':'+'} ${2*Math.abs(q)}y = ${by} − ${q*q}.<br>Итого: ${bx} + ${by} + ${c} − ${p*p} − ${q*q} = ${bx} + ${by} ${m<0?'−':'+'} ${Math.abs(m)}.<br>Оба квадрата ≥ 0 и одновременно равны 0 при x = ${N(p)}, y = ${N(q)}. Наименьшее значение: <b>${N(m)}</b>.`,
explain2:`Подставь x = ${N(p)}, y = ${N(q)}: ${p*p} + ${q*q} ${-2*p*p<0?'−':'+'} ${2*p*p} ${-2*q*q<0?'−':'+'} ${2*q*q} + ${c} = ${N(m)}. Если сдвинуть x или y хоть на 1, один из квадратов станет положительным и значение вырастет. Это как две ямки: самое низкое место — когда стоишь на дне обеих.`};},true);
G(9,()=>{let s,p;do{s=R(3,9);p=R(1,12);}while(s*s<4*p);
return {type:'num',q:`Известно, что ${M(`a + b = ${s}`)} и ${M(`ab = ${p}`)}. Найди ${M('a² + b²')}.`,ans:s*s-2*p,
hint:'(a + b)² = a² + 2ab + b². Что из этого известно?',
short:`a² + b² = (a + b)² − 2ab = ${s*s} − ${2*p} = ${s*s-2*p}.`,
explain:`Из формулы (a + b)² = a² + 2ab + b² выразим a² + b²:<br>a² + b² = (a + b)² − 2ab = ${s}² − 2 · ${p} = ${s*s} − ${2*p} = <b>${s*s-2*p}</b>.<br>Находить сами a и b не нужно!<div class="box err"><b>Ловушка</b>Ответ ${s*s} = ${s}² — забыли вычесть 2ab.</div>`,
explain2:`Посмотри на картинку «квадрат суммы»: весь квадрат со стороной a + b = ${s} имеет площадь ${s*s}. Он состоит из a², b² и двух прямоугольников ab = ${p}. Убираем прямоугольники: ${s*s} − ${p} − ${p} = ${s*s-2*p} — это и есть a² + b².`};},true);
G(9,()=>{let s,p;do{s=R(2,7);p=R(1,10);}while(s*s<4*p);const ans=s**3-3*p*s;
return {type:'num',q:`Известно, что ${M(`a + b = ${s}`)} и ${M(`ab = ${p}`)}. Найди ${M('a³ + b³')}.`,ans,
hint:'(a + b)³ = a³ + b³ + 3ab(a + b).',
short:`a³ + b³ = (a + b)³ − 3ab(a + b) = ${s**3} − ${3*p*s} = ${N(ans)}.`,
explain:`Куб суммы: (a + b)³ = a³ + 3a²b + 3ab² + b³ = a³ + b³ + 3ab(a + b).<br>Отсюда a³ + b³ = (a + b)³ − 3ab(a + b) = ${s}³ − 3 · ${p} · ${s} = ${s**3} − ${3*p*s} = <b>${N(ans)}</b>.`,
explain2:`Другой путь — формула суммы кубов: a³ + b³ = (a + b)(a² − ab + b²).<br>a² + b² = (a + b)² − 2ab = ${s*s} − ${2*p} = ${s*s-2*p}; значит a² − ab + b² = ${s*s-2*p} − ${p} = ${s*s-3*p}.<br>a³ + b³ = ${s} · ${s*s-3*p} = ${N(ans)} ✅.`};},true);
G(9,()=>{const n=R(2,12);const val=n*(n+1)*(n+2)*(n+3)+1,ans=n*n+3*n+1;if(ans*ans!==val)return null;
return {type:'num',q:`Число ${M(`${n} · ${n+1} · ${n+2} · ${n+3} + 1`)} является квадратом натурального числа. Какого?`,ans,
hint:`Перемножь крайние множители и средние отдельно: ${n}·${n+3} и ${n+1}·${n+2}.`,
short:`${n}·${n+3} = ${n*(n+3)}, ${n+1}·${n+2} = ${(n+1)*(n+2)}; ${n*(n+3)} · ${(n+1)*(n+2)} + 1 = ${ans}².`,
explain:`Группируем: (${n} · ${n+3}) · (${n+1} · ${n+2}) + 1 = ${n*(n+3)} · ${(n+1)*(n+2)} + 1.<br>Эти два числа отличаются на 2, а посередине между ними — ${ans}. Значит, это (${ans} − 1)(${ans} + 1) + 1 = ${ans}² − 1 + 1 = ${ans}².<br>Ответ: <b>${ans}</b>.<br>В общем виде: n(n + 1)(n + 2)(n + 3) + 1 = (n² + 3n + 1)². При n = ${n}: ${n*n} + ${3*n} + 1 = ${ans}.`,
explain2:`Проверка: ${n} · ${n+1} · ${n+2} · ${n+3} = ${val-1}, плюс 1 = ${val}. И ${ans}² = ${ans*ans} ✅. Попробуй на маленьком: 1 · 2 · 3 · 4 + 1 = 25 = 5², 2 · 3 · 4 · 5 + 1 = 121 = 11². Всегда квадрат!`};},true);
G(9,()=>{const [a,b]=pick([['a','b'],['x','y'],['m','n']]);
const o=mk(`4${a}${b}`,[`2${a}${b}`,`2${a}² + 2${b}²`,'0']);
return {type:'choice',q:`Упрости: ${M(`(${a} + ${b})² − (${a} − ${b})²`)}.`,opts:o.opts.map(M),ans:o.ans,
short:`(${a}² + 2${a}${b} + ${b}²) − (${a}² − 2${a}${b} + ${b}²) = 4${a}${b}.`,
explain:`(${a} + ${b})² = ${a}² + 2${a}${b} + ${b}²; (${a} − ${b})² = ${a}² − 2${a}${b} + ${b}².<br>Вычитаем: ${a}² + 2${a}${b} + ${b}² − ${a}² + 2${a}${b} − ${b}² = <b>4${a}${b}</b>.<br>• «2${a}${b}» — забыли поменять знак у −2${a}${b} при раскрытии скобки с минусом.<br>• «2${a}² + 2${b}²» — это сумма квадратов (${a} + ${b})² + (${a} − ${b})², а не разность.<br>• «0» — получится, если думать, что (${a} ± ${b})² = ${a}² + ${b}².`,
explain2:`Через разность квадратов: A² − B² = (A − B)(A + B), A = ${a} + ${b}, B = ${a} − ${b}. A − B = 2${b}, A + B = 2${a}. Произведение 4${a}${b}.<br>Проверка числами ${a} = 3, ${b} = 2: 25 − 1 = 24 = 4 · 3 · 2 ✅.`};},true);
G(9,()=>{const k=R(3,8),minus=Math.random()<0.4;const ans=minus?k*k+2:k*k-2;
return {type:'num',q:`Известно, что ${M(`x ${minus?'−':'+'} ${fr(1,'x')} = ${k}`)}. Найди ${M(`x² + ${fr(1,'x²')}`)}.`,ans,
hint:`Возведи обе части равенства в квадрат.`,
short:`(x ${minus?'−':'+'} ${fr(1,'x')})² = x² ${minus?'−':'+'} 2 + ${fr(1,'x²')} = ${k*k} → ответ ${ans}.`,
explain:`Возведём в квадрат: (x ${minus?'−':'+'} ${fr(1,'x')})² = x² ${minus?'−':'+'} 2 · x · ${fr(1,'x')} + ${fr(1,'x²')} = x² ${minus?'−':'+'} 2 + ${fr(1,'x²')}.<br>Удвоенное произведение — просто число 2, потому что x · ${fr(1,'x')} = 1.<br>x² ${minus?'−':'+'} 2 + ${fr(1,'x²')} = ${k}² = ${k*k} → x² + ${fr(1,'x²')} = ${k*k} ${minus?'+':'−'} 2 = <b>${ans}</b>.<div class="box err"><b>Ловушка</b>Ответ ${k*k} — забыли удвоенное произведение.</div>`,
explain2:`Это та же идея, что «знаем a ${minus?'−':'+'} b — найди a² + b²», только b = ${fr(1,'x')} и ab = 1. Формула: a² + b² = (a ${minus?'−':'+'} b)² ${minus?'+':'−'} 2ab = ${k*k} ${minus?'+':'−'} 2 = ${ans}.`};},true);

window.TOPIC={id:'fsu',title:'Формулы сокращённого умножения',subtitle:'Алгебра · 7–8 класс',
intro:`<p>Здесь все формулы сокращённого умножения: квадрат суммы и разности, разность квадратов, кубы. Разберём, как их читать, где обычно ошибаются, как с их помощью считать в уме, раскладывать на множители и искать наименьшее значение. В конце — олимпиадные приёмы. На вкладке «Формулы» — все формулы на одной странице.</p>`,
theory,symbols,figs:{},
levels:['Квадрат суммы','Квадрат разности','Разность квадратов','Считаем в уме','Полный квадрат и разложение','Куб суммы и разности','Сумма и разность кубов','Выделение полного квадрата','Уравнения и упрощение','★ Олимпиадные задачи'],
gens};
})();
